<?php
use App\Services\Workspace;
use App\UI\LiveForm as F;
use App\UI\OrderStatus as S;
use App\UI\UI as U;

$live = Workspace::get()->load(static fn (Workspace $w): array => $w->queue());
$selectedId = is_string($_GET['order'] ?? null) ? $_GET['order'] : null;
$detail = $selectedId ? Workspace::get()->load(static fn (Workspace $w): array => $w->stationOrder($selectedId)) : null;
$here = '/station-admin/orders' . ($selectedId ? '?order=' . rawurlencode($selectedId) : '');
$kindLabel = ['overdue' => 'Waiting too long', 'fee_mismatch' => 'Delivery fee check', 'failed_attempt' => 'Failed delivery', 'empties_mismatch' => 'Empty containers differ', 'capacity' => 'Too big for vehicles', 'closure' => 'Station closure'];
$row = static fn (array $o, string $actions, ?int $pos = null): array => [
    '<a class="font-bold text-water hover:underline" href="/station-admin/orders?order=' . U::e($o['id']) . '">' . U::e($o['order_no']) . '</a>' . ($o['overdue'] ? ' ' . U::badge('Overdue', 'red') : ''),
    '<span class="block font-medium">' . U::e($o['customer_name'] ?? '') . '</span><span class="text-xs text-muted">' . U::e($o['fulfillment'] === 'pickup' ? 'Pickup' : ($o['barangay'] ?? '')) . '</span>',
    (int) $o['total_units'],
    $o['schedule_mode'] === 'scheduled' ? U::e(S::time($o['requested_at'], 'M j, g:i A')) : 'ASAP',
    F::chips($o['score']) . ($pos !== null ? '<span class="mt-1 block text-[11px] text-muted">#' . $pos . ' (estimate)</span>' : ''),
    $actions,
];
$step = static fn (string $action, array $o, string $label, string $variant = 'secondary'): string => F::button($action, ['order_id' => $o['id'], 'expected_version' => $o['version'], 'back' => '/station-admin/orders'], $label, $variant, 'check');
?>
<?= U::heading('Order queue', 'Sorted by priority P = U + A + C. Positions are estimates and change as orders wait or arrive.', U::btn('Deliveries', '/station-admin/deliveries', 'secondary', 'truck') . U::btn('Pickups', '/station-admin/pickups', 'secondary', 'store')) ?>
<?php if (isset($live['error'])): ?><section class="panel p-6" role="alert"><?= U::e($live['error']) ?></section><?php return; endif; ?>
<div data-poll-url="/station-admin/orders/updates" data-poll-version="<?= U::e(Workspace::fingerprint($live)) ?>" data-poll-seconds="30" class="mb-3 rounded-lg bg-foam p-3 text-sm" hidden></div>
<div class="mb-5 grid grid-cols-2 gap-3 xl:grid-cols-4"><?= U::stat('Waiting', (string) count($live['queue']), 'orders', 'blue', 'Confirmed, not started') ?><?= U::stat('Preparing', (string) count($live['preparing']), 'clock', 'amber', 'Being refilled now') ?><?= U::stat('Ready', (string) count($live['ready']), 'check', 'green', 'For a rider or the customer') ?><?= U::stat('Need attention', (string) count($live['reviews']), 'alert', 'red', 'Alerts to resolve') ?></div>
<?php if ($detail !== null): ?>
<section class="panel mb-5 p-4 md:p-5" aria-labelledby="order-detail-title"><?php if (isset($detail['error']) || isset($detail['error_code'])): ?><p role="alert">That order could not be found for this station.</p><?php else: $o = $detail['order']; $pay = $detail['payment']; $fields = ['order_id' => $o['id'], 'expected_version' => $o['version'], 'back' => $here]; ?>
<div class="flex flex-wrap items-start justify-between gap-3"><div><h2 id="order-detail-title" class="section-title"><?= U::e($o['order_no'] ?? '') ?> · <?= U::e($o['contact_name'] ?? '') ?></h2><p class="mt-1 text-sm text-muted"><?= $o['fulfillment'] === 'pickup' ? 'Pickup at the station' : U::e(($o['address_label'] ?? '') . ' — ' . ($o['address_text'] ?? '') . ($o['address_landmark'] ? ' (near ' . $o['address_landmark'] . ')' : '')) ?> · <a class="font-semibold text-water" href="tel:<?= U::e($o['contact_phone'] ?? '') ?>"><?= U::e($o['contact_phone'] ?? '') ?></a></p></div><div class="flex items-center gap-2"><?= S::badge($o['status'], $o['fulfillment']) ?><a class="btn btn-ghost btn-sm" href="/station-admin/orders">Close</a></div></div>
<div class="mt-4 grid gap-5 lg:grid-cols-3"><div class="space-y-3 lg:col-span-2">
<?= U::table(['Item', 'Qty', 'Price', 'Total'], array_map(static fn (array $i): array => [U::e($i['name']), (int) $i['quantity'], S::pesos($i['unit_price_centavos']), S::pesos($i['line_total_centavos'])], $detail['items'])) ?>
<dl class="grid grid-cols-2 gap-2 text-sm sm:grid-cols-4"><div class="rounded-lg bg-mist p-2"><dt class="text-muted">Items</dt><dd class="font-semibold"><?= S::pesos($o['subtotal_centavos']) ?></dd></div><div class="rounded-lg bg-mist p-2"><dt class="text-muted">Delivery fee</dt><dd class="font-semibold"><?= S::pesos($o['final_fee_centavos'] ?? $o['quoted_fee_centavos']) ?><?= $o['distance_display'] !== null ? ' · ' . U::e($o['distance_display']) . ' km' : '' ?></dd></div><div class="rounded-lg bg-mist p-2"><dt class="text-muted">Total</dt><dd class="font-semibold"><?= S::pesos($o['total_centavos']) ?></dd></div><div class="rounded-lg bg-mist p-2"><dt class="text-muted">Priority</dt><dd><?= F::chips($detail['score']) ?></dd></div></dl>
<?php if ($o['note'] !== ''): ?><p class="rounded-lg bg-foam p-3 text-sm"><span class="text-muted">Customer note:</span> <?= U::e($o['note']) ?></p><?php endif ?>
<details class="text-sm"><summary class="cursor-pointer font-semibold text-water">Status history</summary><?= U::table(['When', 'Status', 'Reason'], array_map(static fn (array $l): array => [U::e(S::time($l['at'])), U::e(S::label($l['to'], $o['fulfillment'])), U::e($l['reason'] ?? '')], $detail['timeline'])) ?></details>
</div><div class="space-y-3">
<?php if (in_array($o['status'], ['pending', 'confirmed'], true)): ?><?= F::button('/station-admin/orders/start', $fields, 'Start preparing', 'primary', 'check', null, 'w-full') ?><?php endif ?>
<?php if ($o['status'] === 'preparing'): ?><?= F::button('/station-admin/orders/ready', $fields, $o['fulfillment'] === 'pickup' ? 'Ready for pickup' : 'Ready for delivery', 'primary', 'check', null, 'w-full') ?><?php endif ?>
<?php if ($o['status'] === 'ready' && $o['redispatch_paused']): ?><div class="rounded-lg border border-amber-200 bg-amber-50 p-3"><p class="mb-2 text-sm font-semibold text-amber-900">The last delivery attempt failed. Approve another try when the customer is reachable.</p><?= F::reason('/station-admin/orders/reattempt', $fields, 'Why another try will work', 'Customer confirmed by phone', 'Approve reattempt') ?></div><?php endif ?>
<?php if ($pay !== null): ?><div class="rounded-lg border border-line p-3 text-sm"><p class="font-semibold">Cash <?= $pay['state'] === 'verified' ? U::badge('Verified', 'green') : U::badge('To verify', 'amber') ?></p><p class="mt-1">Applied <?= S::pesos($pay['applied_centavos']) ?> · received <?= S::pesos($pay['tendered_centavos']) ?> · change <?= S::pesos($pay['change_centavos']) ?></p><p>Empty containers: <?= (int) $pay['empties_returned'] ?> of <?= (int) $pay['expected_empties'] ?> expected</p>
<?php if ($pay['state'] === 'unverified'): ?><div class="mt-2"><?= F::open('/station-admin/payments/verify', ['payment_id' => $pay['id'], 'expected_version' => $pay['version'], 'back' => $here], ['class' => 'flex flex-wrap items-end gap-2']) ?><div class="flex-1"><label class="label" for="verify-note">Note (optional)</label><input class="field" id="verify-note" name="note" maxlength="300"></div><?= U::btn('Verify cash', '', 'primary', 'credit', ['type' => 'submit', 'class' => 'btn-sm']) ?></form></div><?php endif ?></div><?php endif ?>
<?php if (in_array($o['status'], ['delivered', 'collected'], true)): ?><?= F::button('/station-admin/orders/complete', $fields, 'Complete order', 'primary', 'check', null, 'w-full') ?><?php endif ?>
<?php foreach ($detail['reviews'] as $rv): if ($rv['state'] !== 'open') continue; ?><div class="rounded-lg border border-rose-200 bg-rose-50 p-3 text-sm"><p class="font-semibold text-rose-900"><?= U::e($kindLabel[$rv['kind']] ?? $rv['kind']) ?></p><p class="mb-2 text-rose-800"><?= U::e($rv['detail']) ?></p>
<?php if ($rv['kind'] === 'fee_mismatch'): ?><?= F::reason('/station-admin/orders/fee-review', $fields, 'Why the quoted fee stands', 'Pin is correct; rider parked farther away', 'Save fee review') ?><?php elseif ($rv['kind'] !== 'failed_attempt'): ?><?= F::reason('/station-admin/reviews/resolve', ['review_id' => $rv['id'], 'expected_version' => $rv['version'], 'back' => $here], 'What you did', 'Called the customer', 'Resolve') ?><?php endif ?></div><?php endforeach ?>
<?php if (in_array($o['status'], ['pending', 'on_hold', 'scheduled', 'confirmed', 'preparing'], true) || ($o['status'] === 'ready' && $pay === null)): ?><details class="rounded-lg border border-line p-3 text-sm"><summary class="cursor-pointer font-semibold text-rose-700">Cancel this order</summary><div class="mt-2"><?= F::reason('/station-admin/orders/cancel', $fields, 'Reason (sent to the customer)', 'Out of containers today', 'Cancel order', 'secondary', 'Cancel this order? The customer will be notified.') ?></div></details><?php endif ?>
<?= U::btn('Message customer', '/station-admin/messages?customer=' . rawurlencode((string) $o['customer_id']), 'ghost', 'message', ['class' => 'w-full']) ?>
</div></div><?php endif ?></section>
<?php endif ?>
<?php if ($live['reviews'] !== []): ?><section class="panel mb-5 border-rose-200 p-4 md:p-5"><?= U::title('Needs attention', 'alert', 'mb-3') ?><ul class="space-y-3"><?php foreach ($live['reviews'] as $rv): ?><li class="rounded-lg bg-rose-50 p-3 text-sm"><p><a class="font-bold text-rose-900 hover:underline" href="/station-admin/orders?order=<?= U::e($rv['order_id']) ?>"><?= U::e($rv['order_no'] ?? '') ?></a> · <?= U::e($kindLabel[$rv['kind']] ?? $rv['kind']) ?>: <?= U::e($rv['detail']) ?></p><?php if (!in_array($rv['kind'], ['failed_attempt', 'fee_mismatch'], true)): ?><div class="mt-2"><?= F::reason('/station-admin/reviews/resolve', ['review_id' => $rv['id'], 'expected_version' => $rv['version'], 'back' => '/station-admin/orders'], 'Resolution', 'Prepared next; customer informed', 'Resolve') ?></div><?php else: ?><a class="mt-1 inline-block font-semibold text-water" href="/station-admin/orders?order=<?= U::e($rv['order_id']) ?>">Open order to decide</a><?php endif ?></li><?php endforeach ?></ul></section><?php endif ?>
<section class="panel mb-5 p-4 md:p-5"><?= U::title('Preparation queue', 'orders', 'mb-1') ?><p class="mb-3 text-xs text-muted">U: 40 ASAP or due within 60 min, 25 within 3 h, 10 later today · A: 5 per 10 minutes waiting, up to 25 · C: institution bonus when enabled. Ties: earlier queue time first.</p>
<?php if ($live['queue'] === []): ?><p class="p-4 text-center text-muted">No orders waiting.</p><?php else: ?><?= U::table(['Order', 'Customer', 'Qty', 'When', 'Priority', ''], array_map(static fn (array $o, int $i): array => $row($o, $step('/station-admin/orders/start', $o, 'Start'), $i + 1), $live['queue'], array_keys($live['queue']))) ?><?php endif ?></section>
<div class="grid gap-5 xl:grid-cols-2">
<section class="panel p-4 md:p-5"><?= U::title('Preparing', 'clock', 'mb-3') ?><?php if ($live['preparing'] === []): ?><p class="p-4 text-center text-muted">Nothing being prepared.</p><?php else: ?><?= U::table(['Order', 'Customer', 'Qty', 'When', 'Priority', ''], array_map(static fn (array $o): array => $row($o, $step('/station-admin/orders/ready', $o, 'Ready', 'primary')), $live['preparing'])) ?><?php endif ?></section>
<section class="panel p-4 md:p-5"><?= U::title('Ready', 'check', 'mb-3') ?><?php if ($live['ready'] === []): ?><p class="p-4 text-center text-muted">No ready orders.</p><?php else: ?><?= U::table(['Order', 'Customer', 'Qty', 'When', 'Priority', ''], array_map(static fn (array $o): array => $row($o, $o['fulfillment'] === 'pickup' ? U::btn('Pickup', '/station-admin/pickups', 'ghost', 'store', ['class' => 'btn-sm']) : ($o['redispatch_paused'] ? U::badge('Paused', 'amber') : U::btn('Dispatch', '/station-admin/deliveries', 'ghost', 'truck', ['class' => 'btn-sm']))), $live['ready'])) ?><?php endif ?></section>
</div>
<div class="mt-5 grid gap-5 xl:grid-cols-3">
<section class="panel p-4 md:p-5"><?= U::title('Waiting for customer', 'alert', 'mb-1') ?><p class="mb-3 text-xs text-muted">Possible repeat orders. Only the customer can confirm them.</p><?php foreach ($live['on_hold'] as $o): ?><p class="border-t border-line py-2 text-sm"><a class="font-semibold text-water" href="/station-admin/orders?order=<?= U::e($o['id']) ?>"><?= U::e($o['order_no']) ?></a> · <?= U::e($o['customer_name'] ?? '') ?></p><?php endforeach ?><?= $live['on_hold'] === [] ? '<p class="text-sm text-muted">None.</p>' : '' ?></section>
<section class="panel p-4 md:p-5"><?= U::title('Scheduled', 'calendar', 'mb-3') ?><?php foreach ($live['scheduled'] as $o): ?><p class="border-t border-line py-2 text-sm"><a class="font-semibold text-water" href="/station-admin/orders?order=<?= U::e($o['id']) ?>"><?= U::e($o['order_no']) ?></a> · <?= U::e(S::time($o['requested_at'], 'D M j, g:i A')) ?></p><?php endforeach ?><?= $live['scheduled'] === [] ? '<p class="text-sm text-muted">None.</p>' : '' ?></section>
<section class="panel p-4 md:p-5"><?= U::title('Awaiting completion', 'credit', 'mb-1') ?><p class="mb-3 text-xs text-muted">Verify the cash and empties, then complete.</p><?php foreach ($live['awaiting_completion'] as $o): ?><p class="border-t border-line py-2 text-sm"><a class="font-semibold text-water" href="/station-admin/orders?order=<?= U::e($o['id']) ?>"><?= U::e($o['order_no']) ?></a> · <?= U::e(S::label($o['status'], $o['fulfillment'])) ?> · <?= S::pesos($o['total_centavos']) ?></p><?php endforeach ?><?= $live['awaiting_completion'] === [] ? '<p class="text-sm text-muted">None.</p>' : '' ?></section>
</div>
